SELECT CAST(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 0 AND 72 THEN e.emar_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 72 AND 84 THEN e.emar_id END), 0) AS proportion_started_within_first_72h, CAST(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 72 AND 84 THEN e.emar_id END) AS FLOAT) - NULLIF(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 0 AND 72 THEN e.emar_id END), 0) AS difference_in_emar_ids_within_last_12h FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.hadm_id = e.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 63 AND a.admittime >= 72 AND a.dischtime <= 84 AND e.medication ilike '%GLP‑1%agonist%';